// The §6.1–§6.3 contract of core/index.ts, read on the bug-surface game (game/game.gb, built by S4).
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { test } from "node:test";
import { GAME_RAM } from "../src/schema.ts";
import type { Core, CreateCore, Handlers } from "../src/schema.ts";
import { createCore as createCoreImpl, HANDLERS as HANDLERS_IMPL } from "./index.ts";

const createCore: CreateCore = createCoreImpl;
const HANDLERS: Handlers = HANDLERS_IMPL;
const ROOT = resolve(import.meta.dirname, "..");
const GAME = resolve(ROOT, "game", "game.gb");
const rom = (): Uint8Array => new Uint8Array(readFileSync(GAME));

/** Frames before the snapshot: past boot and the title's first VBlanks. */
const WARMUP_FRAMES = 120;
/** Frames after the snapshot that both runs must agree on (SPEC §5 S1 Accept). */
const RESUME_FRAMES = 1000;

/** An input schedule keyed by frame index, so the resumed run is fed the same buttons as the straight one. */
const buttonsAt = (f: number): number => ((f >> 6) & 1 ? 0x80 : 0) | ((f >> 4) & 1 ? 0x01 : 0) | ((f >> 5) & 1 ? 0x10 : 0);

function fingerprint(core: Core): string {
  const h = createHash("sha256");
  h.update(core.frame());
  h.update(JSON.stringify({ cpu: core.cpu, cycles: core.cycles, serial: core.serial }));
  h.update(core.snapshot());
  return h.digest("hex");
}

function runFrames(core: Core, from: number, count: number, perFrame?: (f: number) => void): void {
  for (let f = from; f < from + count; f++) {
    core.setButtons(buttonsAt(f));
    core.runFrame();
    perFrame?.(f);
  }
}

test("restore(snapshot()) into a fresh core followed by 1,000 frames equals the straight run's frame, registers, cycles and snapshot", () => {
  const straight = createCore(rom());
  runFrames(straight, 0, WARMUP_FRAMES);
  const snap = straight.snapshot();
  const resumedFrames: string[] = [];
  const straightFrames: string[] = [];
  runFrames(straight, WARMUP_FRAMES, RESUME_FRAMES, () => straightFrames.push(createHash("sha1").update(straight.frame()).digest("hex")));

  const resumed = createCore(rom());
  resumed.restore(snap);
  runFrames(resumed, WARMUP_FRAMES, RESUME_FRAMES, () => resumedFrames.push(createHash("sha1").update(resumed.frame()).digest("hex")));

  assert.deepEqual(resumedFrames, straightFrames);
  assert.equal(fingerprint(resumed), fingerprint(straight));
});

test("HANDLERS holds every handler id the tap emits over 600 frames of the game, each mapped to an existing core/ file", () => {
  const core = createCore(rom());
  const emitted = new Set<string>();
  runFrames(core, 0, 600, () => { for (const [id, n] of Object.entries(core.tap.handlerHits())) if (n > 0) emitted.add(id); });
  assert.ok(emitted.size > 0, "the tap emitted no handler id");
  const missing = [...emitted].filter((id) => !(id in HANDLERS));
  assert.deepEqual(missing, []);
  for (const [id, file] of Object.entries(HANDLERS)) {
    assert.match(file, /^core\//, `${id} → ${file}`);
    assert.ok(existsSync(resolve(ROOT, file)), `${id} → ${file} does not exist`);
  }
});

test("handlerHits resets on read: a second read with no step between returns no positive count", () => {
  const core = createCore(rom());
  core.runFrame();
  core.tap.handlerHits();
  assert.deepEqual(Object.values(core.tap.handlerHits()).filter((n) => n > 0), []);
});

test("runToCounter(n) stops with the game's LE16 counter at 0xC0F0 equal to n, and returns false on a stalled counter", () => {
  const core = createCore(rom());
  assert.equal(core.runToCounter(200), true);
  assert.equal(core.read(GAME_RAM.counter) | (core.read(GAME_RAM.counter + 1) << 8), 200);
  // The lives byte holds still on the title with no buttons pressed, so the run stalls and returns false.
  assert.equal(core.runToCounter(0x1234, GAME_RAM.lives), false);
});

test("runFrame ends at LY 144 and advances 70,224 T-cycles per frame on a running LCD", () => {
  const core = createCore(rom());
  core.runToCounter(60);
  core.runFrame();
  const c0 = core.cycles;
  core.runFrame();
  assert.equal(core.tap.ppu().ly, 144);
  const dt = core.cycles - c0;
  assert.ok(Math.abs(dt - 70_224) <= 24, `frame took ${dt} T-cycles`);
  assert.equal(core.frame().length, 160 * 144);
});
=== END FILE ===

=== FILE: core/cpu.ts ===
import type { HandlerId } from "../src/schema.ts";

export interface CpuBus {
  read(addr: number): number;
  write(addr: number, v: number): void;
  idle(): void;
  pendingIrqs(): number;
  ackIrq(bit: number): void;
}

export class Cpu {
  a = 0x01; b = 0x00; c = 0x13; d = 0x00; e = 0xd8; f = 0xb0;
  h = 0x01; l = 0x4d; sp = 0xfffe; pc = 0x0100;
  ime = false; eiDelay = false; halted = false; haltBug = false;
  hits: Record<HandlerId, number>;
  bus!: CpuBus;
  constructor(hits: Record<HandlerId, number>) { this.hits = hits; }
  attach(bus: CpuBus): void { this.bus = bus; }
  private fetch(): number {
    const v = this.bus.read(this.pc);
    if (this.haltBug) { this.haltBug = false; } else { this.pc = (this.pc + 1) & 0xffff; }
    return v;
  }
  private get hl(): number { return (this.h << 8) | this.l; }
  private set hl(v: number) { this.h = (v >> 8) & 0xff; this.l = v & 0xff; }
  private get bc(): number { return (this.b << 8) | this.c; }
  private get de(): number { return (this.d << 8) | this.e; }
  private aluAdd(v: number, cy: number): void {
    const a = this.a;
    const r = a + v + cy;
    this.f = ((r & 0xff) === 0 ? 0x80 : 0) | ((((a & 0xf) + (v & 0xf) + cy) > 0xf) ? 0x20 : 0) | (((a + v + cy) > 0xff) ? 0x10 : 0);
    this.a = r & 0xff;
  }
  private aluSub(v: number, cy: number): void {
    const a = this.a;
    const r = a - v - cy;
    this.f = 0x40 | (((r & 0xff) === 0) ? 0x80 : 0) | ((((a & 0xf) - (v & 0xf) - cy) < 0) ? 0x20 : 0) | (((a - v - cy) < 0) ? 0x10 : 0);
    this.a = r & 0xff;
  }
  private aluAnd(v: number): void { this.a &= v; this.f = (this.a === 0 ? 0x80 : 0) | 0x20; }
  private aluOr(v: number): void { this.a |= v; this.a &= 0xff; this.f = this.a === 0 ? 0x80 : 0; }
  private aluXor(v: number): void { this.a ^= v; this.a &= 0xff; this.f = this.a === 0 ? 0x80 : 0; }
  private aluCp(v: number): void {
    const a = this.a;
    const r = a - v;
    this.f = 0x40 | (((r & 0xff) === 0) ? 0x80 : 0) | (((a & 0xf) < (v & 0xf)) ? 0x20 : 0) | ((a < v) ? 0x10 : 0);
  }
  private aluInc(v: number): number {
    const r = (v + 1) & 0xff;
    this.f = (this.f & 0x10) | (r === 0 ? 0x80 : 0) | ((v & 0xf) === 0xf ? 0x20 : 0);
    return r;
  }
  private aluDec(v: number): number {
    const r = (v - 1) & 0xff;
    this.f = (this.f & 0x10) | 0x40 | (r === 0 ? 0x80 : 0) | ((v & 0xf) === 0 ? 0x20 : 0);
    return r;
  }
  private addHl(v: number): void {
    const hl = this.hl;
    const r = hl + v;
    this.f = (this.f & 0x80) | ((((hl & 0xfff) + (v & 0xfff)) > 0xfff) ? 0x20 : 0) | ((r > 0xffff) ? 0x10 : 0);
    this.hl = r & 0xffff;
  }
  private rlc(v: number): number {
    const c = (v >> 7) & 1;
    const r = ((v << 1) | c) & 0xff;
    this.f = (r === 0 ? 0x80 : 0) | (c ? 0x10 : 0);
    return r;
  }
  private rrc(v: number): number {
    const c = v & 1;
    const r = ((v >> 1) | (c << 7)) & 0xff;
    this.f = (r === 0 ? 0x80 : 0) | (c ? 0x10 : 0);
    return r;
  }
  private rl(v: number): number {
    const c = (this.f >> 4) & 1;
    const nc = (v >> 7) & 1;
    const r = ((v << 1) | c) & 0xff;
    this.f = (r === 0 ? 0x80 : 0) | (nc ? 0x10 : 0);
    return r;
  }
  private rr(v: number): number {
    const c = (this.f >> 4) & 1;
    const nc = v & 1;
    const r = ((v >> 1) | (c << 7)) & 0xff;
    this.f = (r === 0 ? 0x80 : 0) | (nc ? 0x10 : 0);
    return r;
  }
  private sla(v: number): number {
    const nc = (v >> 7) & 1;
    const r = (v << 1) & 0xff;
    this.f = (r === 0 ? 0x80 : 0) | (nc ? 0x10 : 0);
    return r;
  }
  private sra(v: number): number {
    const nc = v & 1;
    const r = ((v >> 1) | (v & 0x80)) & 0xff;
    this.f = (r === 0 ? 0x80 : 0) | (nc ? 0x10 : 0);
    return r;
  }
  private srl(v: number): number {
    const nc = v & 1;
    const r = (v >> 1) & 0xff;
    this.f = (r === 0 ? 0x80 : 0) | (nc ? 0x10 : 0);
    return r;
  }
  private swap(v: number): number {
    const r = ((v << 4) | (v >> 4)) & 0xff;
    this.f = r === 0 ? 0x80 : 0;
    return r;
  }
  private bit(n: number, v: number): void {
    this.f = (this.f & 0x10) | 0x20 | ((((v >> n) & 1) === 0) ? 0x80 : 0);
  }
  step(): void {
    if (this.halted) {
      const p = this.bus.pendingIrqs();
      if (p !== 0) {
        this.halted = false;
        if (!this.ime) { this.bus.idle(); return; }
      } else { this.bus.idle(); return; }
    }
    if (!this.eiDelay && this.ime) {
      const p = this.bus.pendingIrqs();
      if (p !== 0) {
        let bit = 0;
        while (((p >> bit) & 1) === 0) bit++;
        this.hits["irq"] = (this.hits["irq"] || 0) + 1;
        this.ime = false;
        this.bus.ackIrq(bit);
        this.bus.idle();
        this.bus.idle();
        this.sp = (this.sp - 1) & 0xffff;
        this.bus.write(this.sp, (this.pc >> 8) & 0xff);
        this.sp = (this.sp - 1) & 0xffff;
        this.bus.write(this.sp, this.pc & 0xff);
        this.bus.idle();
        this.pc = (0x40 + bit * 8) & 0xffff;
        return;
      }
    }
    const delayed = this.eiDelay;
    if (delayed) this.eiDelay = false;
    const op = this.fetch();
    this.hits["cpu.op"] = (this.hits["cpu.op"] || 0) + 1;
    this.exec(op);
    if (delayed) this.ime = true;
  }
  private jr(cond: boolean): void {
    const e = this.fetch();
    if (cond) { this.bus.idle(); this.pc = (this.pc + ((e ^ 0x80) - 0x80)) & 0xffff; }
  }
  private jp(cond: boolean): void {
    const lo = this.fetch();
    const hi = this.fetch();
    if (cond) { this.bus.idle(); this.pc = (lo | (hi << 8)) & 0xffff; }
  }
  private call(cond: boolean): void {
    const lo = this.fetch();
    const hi = this.fetch();
    if (cond) {
      this.bus.idle();
      this.sp = (this.sp - 1) & 0xffff;
      this.bus.write(this.sp, (this.pc >> 8) & 0xff);
      this.sp = (this.sp - 1) & 0xffff;
      this.bus.write(this.sp, this.pc & 0xff);
      this.pc = (lo | (hi << 8)) & 0xffff;
    }
  }
  private ret(cond: boolean): void {
    if (cond) {
      this.bus.idle();
      const lo = this.bus.read(this.sp);
      this.sp = (this.sp + 1) & 0xffff;
      const hi = this.bus.read(this.sp);
      this.sp = (this.sp + 1) & 0xffff;
      this.bus.idle();
      this.pc = (lo | (hi << 8)) & 0xffff;
    } else this.bus.idle();
  }
  private rst(v: number): void {
    this.bus.idle();
    this.sp = (this.sp - 1) & 0xffff;
    this.bus.write(this.sp, (this.pc >> 8) & 0xff);
    this.sp = (this.sp - 1) & 0xffff;
    this.bus.write(this.sp, this.pc & 0xff);
    this.pc = v;
  }
  private exec(op: number): void {
    const B = this.bus;
    switch (op) {
      case 0x00: break;
      case 0x01: this.c = this.fetch(); this.b = this.fetch(); break;
      case 0x02: B.write(this.bc, this.a); break;
      case 0x03: B.idle(); { const v = (this.bc + 1) & 0xffff; this.b = (v >> 8) & 0xff; this.c = v & 0xff; } break;
      case 0x04: this.b = this.aluInc(this.b); break;
      case 0x05: this.b = this.aluDec(this.b); break;
      case 0x06: this.b = this.fetch(); break;
      case 0x07: { const c = (this.a >> 7) & 1; this.a = ((this.a << 1) | c) & 0xff; this.f = c ? 0x10 : 0; } break;
      case 0x08: { const lo = this.fetch(); const hi = this.fetch(); const a = lo | (hi << 8); B.write(a, this.sp & 0xff); B.write((a + 1) & 0xffff, (this.sp >> 8) & 0xff); } break;
      case 0x09: this.addHl(this.bc); B.idle(); break;
      case 0x0a: this.a = B.read(this.bc); break;
      case 0x0b: B.idle(); { const v = (this.bc - 1) & 0xffff; this.b = (v >> 8) & 0xff; this.c = v & 0xff; } break;
      case 0x0c: this.c = this.aluInc(this.c); break;
      case 0x0d: this.c = this.aluDec(this.c); break;
      case 0x0e: this.c = this.fetch(); break;
      case 0x0f: { const c = this.a & 1; this.a = ((this.a >> 1) | (c << 7)) & 0xff; this.f = c ? 0x10 : 0; } break;
      case 0x10: { this.fetch(); B.idle(); B.idle(); B.idle(); break; }
      case 0x11: this.e = this.fetch(); this.d = this.fetch(); break;
      case 0x12: B.write(this.de, this.a); break;
      case 0x13: B.idle(); { const v = (this.de + 1) & 0xffff; this.d = (v >> 8) & 0xff; this.e = v & 0xff; } break;
      case 0x14: this.d = this.aluInc(this.d); break;
      case 0x15: this.d = this.aluDec(this.d); break;
      case 0x16: this.d = this.fetch(); break;
      case 0x17: { const c = (this.f >> 4) & 1; const nc = (this.a >> 7) & 1; this.a = ((this.a << 1) | c) & 0xff; this.f = nc ? 0x10 : 0; } break;
      case 0x18: this.jr(true); break;
      case 0x19: this.addHl(this.de); B.idle(); break;
      case 0x1a: this.a = B.read(this.de); break;
      case 0x1b: B.idle(); { const v = (this.de - 1) & 0xffff; this.d = (v >> 8) & 0xff; this.e = v & 0xff; } break;
      case 0x1c: this.e = this.aluInc(this.e); break;
      case 0x1d: this.e = this.aluDec(this.e); break;
      case 0x1e: this.e = this.fetch(); break;
      case 0x1f: { const c = (this.f >> 4) & 1; const nc = this.a & 1; this.a = ((this.a >> 1) | (c << 7)) & 0xff; this.f = nc ? 0x10 : 0; } break;
      case 0x20: this.jr((this.f & 0x80) === 0); break;
      case 0x21: this.l = this.fetch(); this.h = this.fetch(); break;
      case 0x22: B.write(this.hl, this.a); this.hl = (this.hl + 1) & 0xffff; break;
      case 0x23: B.idle(); this.hl = (this.hl + 1) & 0xffff; break;
      case 0x24: this.h = this.aluInc(this.h); break;
      case 0x25: this.h = this.aluDec(this.h); break;
      case 0x26: this.h = this.fetch(); break;
      case 0x27: {
        let a = this.a;
        let adj = 0;
        const c = (this.f & 0x10) !== 0;
        const h = (this.f & 0x20) !== 0;
        const n = (this.f & 0x40) !== 0;
        if (!n) { if (h || (a & 0xf) > 9) adj |= 0x06; if (c || a > 0x99) adj |= 0x60; a += adj; }
        else { if (h) adj |= 0x06; if (c) adj |= 0x60; a -= adj; }
        this.a = a & 0xff;
        this.f = (this.f & 0x40) | (this.a === 0 ? 0x80 : 0) | ((adj & 0x60) !== 0 ? 0x10 : 0);
        break;
      }
      case 0x28: this.jr((this.f & 0x80) !== 0); break;
      case 0x29: this.addHl(this.hl); B.idle(); break;
      case 0x2a: this.a = B.read(this.hl); this.hl = (this.hl + 1) & 0xffff; break;
      case 0x2b: B.idle(); this.hl = (this.hl - 1) & 0xffff; break;
      case 0x2c: this.l = this.aluInc(this.l); break;
      case 0x2d: this.l = this.aluDec(this.l); break;
      case 0x2e: this.l = this.fetch(); break;
      case 0x2f: this.a = (~this.a) & 0xff; this.f |= 0x60; break;
      case 0x30: this.jr((this.f & 0x10) === 0); break;
      case 0x31: { const lo = this.fetch(); const hi = this.fetch(); this.sp = (lo | (hi << 8)) & 0xffff; } break;
      case 0x32: B.write(this.hl, this.a); this.hl = (this.hl - 1) & 0xffff; break;
      case 0x33: B.idle(); this.sp = (this.sp + 1) & 0xffff; break;
      case 0x34: { const v = B.read(this.hl); B.write(this.hl, this.aluInc(v)); } break;
      case 0x35: { const v = B.read(this.hl); B.write(this.hl, this.aluDec(v)); } break;
      case 0x36: { const n = this.fetch(); B.write(this.hl, n); } break;
      case 0x37: this.f = (this.f & 0x80) | 0x10; break;
      case 0x38: this.jr((this.f & 0x10) !== 0); break;
      case 0x39: this.addHl(this.sp); B.idle(); break;
      case 0x3a: this.a = B.read(this.hl); this.hl = (this.hl - 1) & 0xffff; break;
      case 0x3b: B.idle(); this.sp = (this.sp - 1) & 0xffff; break;
      case 0x3c: this.a = this.aluInc(this.a); break;
      case 0x3d: this.a = this.aluDec(this.a); break;
      case 0x3e: this.a = this.fetch(); break;
      case 0x3f: this.f = (this.f & 0x80) | (((this.f & 0x10) !== 0) ? 0 : 0x10); break;
      case 0x40: break;
      case 0x41: this.b = this.c; break;
      case 0x42: this.b = this.d; break;
      case 0x43: this.b = this.e; break;
      case 0x44: this.b = this.h; break;
      case 0x45: this.b = this.l; break;
      case 0x46: this.b = B.read(this.hl); break;
      case 0x47: this.b = this.a; break;
      case 0x48: this.c = this.b; break;
      case 0x49: break;
      case 0x4a: this.c = this.d; break;
      case 0x4b: this.c = this.e; break;
      case 0x4c: this.c = this.h; break;
      case 0x4d: this.c = this.l; break;
      case 0x4e: this.c = B.read(this.hl); break;
      case 0x4f: this.c = this.a; break;
      case 0x50: this.d = this.b; break;
      case 0x51: this.d = this.c; break;
      case 0x52: break;
      case 0x53: this.d = this.e; break;
      case 0x54: this.d = this.h; break;
      case 0x55: this.d = this.l; break;
      case 0x56: this.d = B.read(this.hl); break;
      case 0x57: this.d = this.a; break;
      case 0x58: this.e = this.b; break;
      case 0x59: this.e = this.c; break;
      case 0x5a: this.e = this.d; break;
      case 0x5b: break;
      case 0x5c: this.e = this.h; break;
      case 0x5d: this.e = this.l; break;
      case 0x5e: this.e = B.read(this.hl); break;
      case 0x5f: this.e = this.a; break;
      case 0x60: this.h = this.b; break;
      case 0x61: this.h = this.c; break;
      case 0x62: this.h = this.d; break;
      case 0x63: this.h = this.e; break;
      case 0x64: break;
      case 0x65: this.h = this.l; break;
      case 0x66: this.h = B.read(this.hl); break;
      case 0x67: this.h = this.a; break;
      case 0x68: this.l = this.b; break;
