      case 0xff02: return (sc & 0xff) | 0x7c;
      case 0xff04: return (div >> 8) & 0xff;
      case 0xff05: return tima & 0xff;
      case 0xff06: return tma & 0xff;
      case 0xff07: return 0xf8 | (tac & 0x07);
