  const cpu = new Cpu(hits);
  const bus: CpuBus = {
    read(a: number): number {
      a &= 0xffff;
      tick(4);
      return peek(a);
    },
    write(a: number, v: number): void {
      a &= 0xffff; v &= 0xff;
