    buf[o++] = cpu.halted ? 1 : 0; buf[o++] = cpu.haltBug ? 1 : 0;
    dv.setUint16(o, div, true); o += 2;
    buf[o++] = tima; buf[o++] = tma; buf[o++] = tac; buf[o++] = prevAnd; buf[o++] = reload;
    buf[o++] = IF; buf[o++] = IE;
    buf[o++] = p1; buf[o++] = joyMask; buf[o++] = sb; buf[o++] = sc;
