    cpu.halted = s[o++] !== 0; cpu.haltBug = s[o++] !== 0;
    div = dv.getUint16(o, true); o += 2;
    tima = s[o++]; tma = s[o++]; tac = s[o++]; prevAnd = s[o++]; reload = s[o++];
    IF = s[o++]; IE = s[o++];
    p1 = s[o++]; joyMask = s[o++]; sb = s[o++]; sc = s[o++];
