      ppu.histBgp.set(s.subarray(o, o + 456)); o += 456;
      ppu.histObp0.set(s.subarray(o, o + 456)); o += 456;
      ppu.histObp1.set(s.subarray(o, o + 456)); o += 456;
      ppu.histWy.set(s.subarray(o, o + 456)); o += 456;
      ppu.histWx.set(s.subarray(o, o + 456)); o += 456;
